import java.net.*; import java.net.http.*; import java.nio.file.*; import java.time.*;
class SchoolProbe { public static void main(String[] args) throws Exception { for(var version: new HttpClient.Version[]{HttpClient.Version.HTTP_2,HttpClient.Version.HTTP_1_1}) { try { var client=HttpClient.newBuilder().version(version).connectTimeout(Duration.ofSeconds(5)).build(); var request=HttpRequest.newBuilder(URI.create("http://10.138.50.151:8000/v1/chat/completions")).timeout(Duration.ofSeconds(12)).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(Files.readString(Path.of("school-probe.json")))).build(); var response=client.send(request,HttpResponse.BodyHandlers.ofString()); System.out.println(version+" status="+response.statusCode()+" body="+response.body().substring(0,Math.min(250,response.body().length()))); } catch(Exception e){System.out.println(version+" "+e.getClass().getSimpleName()+" "+e.getMessage());} } } }
